import{_ as t}from"./chunks/thumb-04.CWQfosSq.js";import{_ as o}from"./chunks/photo-04.bq1lwg32.js";import{_ as a,H as r,f as s,i}from"./chunks/framework.Cvt1eIE0.js";const A=JSON.parse('{"title":"OpenAI Codex 使用教程：IDE 插件与 CLI 工程 Agent","description":"","frontmatter":{"title":"OpenAI Codex 使用教程：IDE 插件与 CLI 工程 Agent","date":"2026-05-22T00:00:00.000Z","category":"技术","tags":["AI","OpenAI Codex","教程"],"excerpt":"面向软件工程任务的 Codex：在 Cursor/VS Code 中安装、ChatGPT 登录、模型选择与任务拆分。"},"headers":[],"relativePath":"posts/技术/openai-codex-tutorial.md","filePath":"posts/技术/openai-codex-tutorial.md"}'),n={name:"posts/技术/openai-codex-tutorial.md"};function d(l,e,c,p,h,g){return r(),s("div",null,[...e[0]||(e[0]=[i('<img src="'+t+'" alt="配图" class="article-banner" loading="lazy"><div class="figure wide"><img src="'+o+'" alt="随拍配图" loading="lazy"><p class="figure-caption">工程 Agent 的价值在闭环，而不在单行补全。</p></div><h1 id="openai-codex-使用教程" tabindex="-1">OpenAI Codex 使用教程 <a class="header-anchor" href="#openai-codex-使用教程" aria-label="Permalink to &quot;OpenAI Codex 使用教程&quot;">​</a></h1><p>OpenAI <strong>Codex</strong>（2025–2026 产品线中的工程 Agent）定位是参与真实开发流程：读仓库、改多文件、跑命令、协助 Code Review。与早期「只补全 API」不同，当前形态更接近<strong>可授权执行的编程代理</strong>。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li><strong>ChatGPT Plus / Pro / Business</strong> 或团队授权（政策以 OpenAI 为准）</li><li>稳定访问 OpenAI 服务</li><li>推荐宿主：<strong>Cursor</strong>、VS Code，或支持 Codex 扩展的 IDE</li></ul><h2 id="在-cursor-中安装-常见路径" tabindex="-1">在 Cursor 中安装（常见路径） <a class="header-anchor" href="#在-cursor-中安装-常见路径" aria-label="Permalink to &quot;在 Cursor 中安装（常见路径）&quot;">​</a></h2><ol><li>打开扩展市场，搜索 <strong>Codex</strong> 官方插件并安装。</li><li>打开任意文件，从侧边栏或命令面板进入 Codex 面板。</li><li>选择 <strong>Sign in with ChatGPT</strong>，浏览器完成 OAuth。</li><li>在设置中将默认模型切到 <strong>GPT-5.x-Codex</strong>（名称随版本更新）。</li><li>按需开启 <strong>Full Access</strong>（文件与终端权限）；企业项目建议先在分支上试用。</li></ol><h2 id="适合交给-codex-的任务" tabindex="-1">适合交给 Codex 的任务 <a class="header-anchor" href="#适合交给-codex-的任务" aria-label="Permalink to &quot;适合交给 Codex 的任务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>示例</th></tr></thead><tbody><tr><td>实现</td><td>「按 <code>docs/spec.md</code> 实现导出 CSV 接口」</td></tr><tr><td>重构</td><td>「把 <code>legacy/</code> 下回调改为 async/await」</td></tr><tr><td>审查</td><td>「检查 PR 中鉴权遗漏」</td></tr><tr><td>运维脚本</td><td>「写 GitHub Actions 缓存 Flutter 依赖」</td></tr></tbody></table><p>每条任务应包含：<strong>完成定义</strong>（测试命令、截图、接口契约）。</p><h2 id="工作流建议" tabindex="-1">工作流建议 <a class="header-anchor" href="#工作流建议" aria-label="Permalink to &quot;工作流建议&quot;">​</a></h2><ol><li><strong>开分支</strong>：<code>git checkout -b codex/feature-x</code></li><li><strong>缩小范围</strong>：一次只改一个模块，避免整仓重写</li><li><strong>让它跑测试</strong>：在提示里写 <code>flutter test</code> / <code>pytest</code> 必须通过</li><li><strong>人工 Review diff</strong>：重点看安全、并发、边界条件</li><li><strong>合并前 squash 或整理提交信息</strong></li></ol><h2 id="与-api-开发的关系" tabindex="-1">与 API 开发的关系 <a class="header-anchor" href="#与-api-开发的关系" aria-label="Permalink to &quot;与 API 开发的关系&quot;">​</a></h2><p>Plus 用户往往<strong>无需单独 API Key</strong> 即可在 IDE 使用 Codex；若要做 CI Headless、自定义流水线，再查阅 OpenAI 是否提供 CLI/API 形态及计费。</p><h2 id="与-deepseek-等开源模型" tabindex="-1">与 DeepSeek 等开源模型 <a class="header-anchor" href="#与-deepseek-等开源模型" aria-label="Permalink to &quot;与 DeepSeek 等开源模型&quot;">​</a></h2><p>开源模型适合自建推理、成本可控；Codex 优势通常在<strong>复杂工程调度与工具链整合</strong>。可按任务类型分工具，而非只留一个。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q：登录失败？</strong><br> A：确认订阅档、系统时间、代理；清理浏览器 Cookie 后重试 OAuth。</p><p><strong>Q：和 Cursor 自带 Agent 重复吗？</strong><br> A：可并存，但避免对同一任务开两套 Agent 同时改文件。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>收藏区：<a href="/posts/收藏/appark-openai-codex-guide-gpt55-vs-deepseekv4.html">Appark 转载 · Codex 实战与 DeepSeek 对比</a></li></ul><hr><p><em>模型名称与权限以 OpenAI 官方文档为准。</em></p>',24)])])}const m=a(n,[["render",d]]);export{A as __pageData,m as default};
